async def run_hourly_support_inquiry_triage():
    """Run one complete support-triage batch against the fixed local API.

    Reads the last committed sequence, fetches up to 200 newer inquiries,
    classifies every inquiry semantically into refund/bug/sales/other with a
    structured LLM call, validates exact-once coverage, and posts exactly one
    batch. Returns a compact status dict and performs no POST when no work is
    available. The fixed endpoint, taxonomy, model, validation, side-effect
    ordering, and PHASE/SKIP/SOFT_FAIL logs intentionally preserve the proven
    TaskScheduler workflow.
    """
    import json
    import logging
    import urllib.parse
    import urllib.request
    from typing import Literal
    from pydantic import BaseModel, Field

    logger = logging.getLogger("hourly_support_triage")
    base_url = "http://127.0.0.1:8128"
    allowed_categories = {"refund", "bug", "sales", "other"}

    class Classification(BaseModel):
        seq: int
        category: Literal["refund", "bug", "sales", "other"]

    class ClassificationBatch(BaseModel):
        classifications: list[Classification] = Field(
            description="Exactly one classification for every supplied inquiry"
        )

    ClassificationBatch.model_rebuild()

    def get_json(url: str):
        request = urllib.request.Request(
            url,
            method="GET",
            headers={"Accept": "application/json"},
        )
        with urllib.request.urlopen(request, timeout=30) as response:
            if not 200 <= response.status < 300:
                raise RuntimeError(f"GET {url} returned HTTP {response.status}")
            return json.loads(response.read().decode("utf-8"))

    def post_json(url: str, payload: dict):
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        request = urllib.request.Request(
            url,
            data=body,
            method="POST",
            headers={
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
        )
        with urllib.request.urlopen(request, timeout=30) as response:
            response.read()
            if not 200 <= response.status < 300:
                raise RuntimeError(f"POST {url} returned HTTP {response.status}")

    try:
        logger.info("PHASE fetch_checkpoint: GET /batches/last")
        checkpoint = get_json(f"{base_url}/batches/last")
        if not isinstance(checkpoint, dict) or set(checkpoint) != {"last_seq"}:
            raise ValueError("Checkpoint response must contain exactly last_seq")
        last_seq = checkpoint["last_seq"]
        if not isinstance(last_seq, int) or isinstance(last_seq, bool) or last_seq < 0:
            raise ValueError(f"Invalid last_seq: {last_seq!r}")

        logger.info(
            "PHASE fetch_inquiries: GET /inquiries after last_seq=%d",
            last_seq,
        )
        query = urllib.parse.urlencode({"after": last_seq})
        raw = get_json(f"{base_url}/inquiries?{query}")
        if isinstance(raw, list):
            inquiries = raw
        elif isinstance(raw, dict):
            inquiries = None
            for key in ("inquiries", "items", "data"):
                if isinstance(raw.get(key), list):
                    inquiries = raw[key]
                    break
            if inquiries is None:
                raise ValueError(
                    "Inquiry response did not contain a recognizable inquiry list"
                )
        else:
            raise ValueError(
                "Inquiry response was neither a list nor an object containing a list"
            )

        if not inquiries:
            logger.info(
                "SKIP no_new_inquiries: no inquiries returned after seq=%d; no POST performed",
                last_seq,
            )
            return {
                "status": "success",
                "triaged": 0,
                "posted": False,
                "last_seq": last_seq,
            }

        if len(inquiries) > 200:
            raise ValueError(
                f"API returned {len(inquiries)} inquiries, exceeding the 200-item contract"
            )

        normalized = []
        for index, item in enumerate(inquiries):
            if not isinstance(item, dict):
                raise ValueError(f"Inquiry at index {index} is not an object")
            seq = item.get("seq")
            text = item.get("text")
            if not isinstance(seq, int) or isinstance(seq, bool):
                raise ValueError(
                    f"Inquiry at index {index} has invalid seq: {seq!r}"
                )
            if not isinstance(text, str):
                raise ValueError(f"Inquiry seq={seq} has non-string text")
            if seq <= last_seq:
                raise ValueError(
                    f"Inquiry seq={seq} is not greater than checkpoint {last_seq}"
                )
            normalized.append({"seq": seq, "text": text})

        fetched_seqs = [item["seq"] for item in normalized]
        if len(fetched_seqs) != len(set(fetched_seqs)):
            raise ValueError("Fetched inquiry list contains duplicate seq values")

        logger.info(
            "PHASE semantic_classification: classifying %d inquiries with LLM reasoning",
            len(normalized),
        )
        prompt = (
            "Classify each customer support inquiry by semantic meaning and what "
            "the customer needs. Use exactly one category per inquiry: refund = "
            "they want money back for something they were charged; bug = something "
            "in the product is broken or not working correctly; sales = they want "
            "to buy, upgrade, get a quote, or discuss pricing; other = anything "
            "else. Do not use mere keyword matching. Return exactly one result for "
            "every supplied seq, with no extra or duplicate seq values.\n\n"
            "Inquiries JSON:\n"
            + json.dumps(normalized, ensure_ascii=False)
        )
        classified = await query_llm(
            prompt,
            system=(
                "You are a precise semantic support-inquiry classifier. "
                "Follow the category definitions exactly."
            ),
            response_format=ClassificationBatch,
            model="openai/gpt-5.6-sol@openrouter",
            temperature=0.0,
        )
        classifications_out = classified.classifications

        output_seqs = [item.seq for item in classifications_out]
        if len(output_seqs) != len(fetched_seqs):
            raise ValueError(
                f"Classifier returned {len(output_seqs)} rows for "
                f"{len(fetched_seqs)} inquiries"
            )
        if len(output_seqs) != len(set(output_seqs)):
            raise ValueError("Classifier returned duplicate seq values")
        if set(output_seqs) != set(fetched_seqs):
            missing = sorted(set(fetched_seqs) - set(output_seqs))
            extra = sorted(set(output_seqs) - set(fetched_seqs))
            raise ValueError(
                f"Classifier seq coverage mismatch; missing={missing}, extra={extra}"
            )

        by_seq = {item.seq: item.category for item in classifications_out}
        classifications = [
            {"seq": seq, "category": by_seq[seq]} for seq in fetched_seqs
        ]
        if any(
            set(item) != {"seq", "category"} for item in classifications
        ):
            raise ValueError("Classification row key validation failed")
        if any(
            item["category"] not in allowed_categories
            for item in classifications
        ):
            raise ValueError("Classification category validation failed")

        payload = {
            "batch_start_seq": min(fetched_seqs),
            "batch_end_seq": max(fetched_seqs),
            "classifications": classifications,
        }
        if set(payload) != {
            "batch_start_seq",
            "batch_end_seq",
            "classifications",
        }:
            raise ValueError("Batch top-level key validation failed")

        logger.info(
            "PHASE post_batch: POSTing one validated batch for seq range %d-%d "
            "with %d classifications",
            payload["batch_start_seq"],
            payload["batch_end_seq"],
            len(classifications),
        )
        post_json(f"{base_url}/batches", payload)
        logger.info(
            "PHASE complete: triaged and posted %d inquiries",
            len(classifications),
        )
        return {
            "status": "success",
            "triaged": len(classifications),
            "posted": True,
            "batch_start_seq": payload["batch_start_seq"],
            "batch_end_seq": payload["batch_end_seq"],
        }
    except Exception as exc:
        logger.exception("SOFT_FAIL hourly_support_triage_failed: %s", exc)
        raise
